-- Section 1: Unified Item Catalog (replaces VENDOR_REAGENTS, EXTRA_NAMES, RItem, MP.EXTRA_VENDOR_REAGENTS & MP.ITEM_INFO)
ns.ITEMS = {}
ns.VENDOR_REAGENTS = {}
ns.ITEM_VENDOR_SELL = {}
ns.ITEM_BOP = {}
MP.ITEM_INFO = {}
local function I(id, name, sell, buy, vbuy, bop, mpFlag)
	ns.RegisterItem(id, name)
	local hasMP = mpFlag ~= nil or buy ~= nil
	local mpBuy = (buy ~= nil and buy ~= -1) and buy or nil
	local vendorPrice = (vbuy == true and mpBuy) or (type(vbuy) == 'number' and vbuy) or nil
	ns.ITEMS[id] = { id = id, name = name, sell = sell, buy = mpBuy, vendorPrice = vendorPrice, bop = bop == true }
	if sell ~= nil then ns.ITEM_VENDOR_SELL[id] = sell end
	if bop == true then ns.ITEM_BOP[id] = true end
	if vendorPrice ~= nil then ns.VENDOR_REAGENTS[id] = vendorPrice end
	if hasMP then
		local mpName = (type(mpFlag) == 'table' and mpFlag.n) or name
		local mpSell = (type(mpFlag) == 'table' and mpFlag.s) or sell
		MP.ITEM_INFO[id] = { name = mpName, sell = mpSell, buy = mpBuy, bop = bop == true }
	end
end

