-- Section 2: Unified Recipe Catalog (replaces Data_Recipes + M + MP.RECIPES; single row per recipe)
ns.RECIPES = {}
ns.CAMP_RECIPES_BY_REP = { [0] = {}, [5] = {}, [6] = {}, [7] = {}, [8] = {} }
MP.RECIPES = {}
for _, pk in ipairs(MP.PROF_ORDER) do MP.RECIPES[pk] = {} end
MP.RECIPES_BY_SPELL = {}
local campSlots = { [0] = {}, [5] = {}, [6] = {}, [7] = {}, [8] = {} }

local function cloneReagents(r)
	if not r then return nil end
	local out = {}
	for i = 1, #r do out[i] = { r[i][1], r[i][2] } end
	return out
end

local function mpVal(override, fallback)
	if override == false then return nil end
	if override ~= nil then return override end
	return fallback
end

ns.RECIPE_CAST_TIME_MS = ns.RECIPE_CAST_TIME_MS or {}

local function R(t)
	if type(t.ct) == 'number' then
		if t.s then ns.RECIPE_CAST_TIME_MS[t.s] = t.ct end
		if t.mpS then ns.RECIPE_CAST_TIME_MS[t.mpS] = t.ct end
	end
	if not t.mpOnly then
		local outID = t.i
		local recID = t.ri
		local reagents = (type(t.mpR) == 'table' and t.mpR) or t.r or {}
		for _, rg in ipairs(reagents) do ns.ALL_CATALOG_IDS[rg[1]] = true end
		local isEnch = t.ench == true
		local isBoP = outID ~= nil and ns.ITEM_BOP[outID] == true
		local sellable = t.sell
		if sellable == nil then sellable = (not isEnch) and (not isBoP) and (outID ~= nil) end
		local prof = t.prof or t.pk
		local entry = {
			idx = t.idx,
			spellID = t.s,
			recipeItemID = recID,
			outputItemID = outID,
			name = t.n,
			recipeName = t.rn or t.n,
			prof = prof,
			skill = t.skill,
			rep = t.rep or 0,
			repFactionID = t.repFacID,
			repFaction = t.repFac,
			favorCost = t.fav or 0,
			source = t.source,
			acqType = t.acq,
			numMade = t.c or 1,
			sellable = sellable,
			isEnchant = isEnch,
			reagents = reagents,
			trainerCost = t.tc,
			recipeVendorPrice = t.rbuy,
			vendorA = t.vA,
			vendorH = t.vH,
			vendorAll = t.vAll,
			reqCharLevel = t.rlv,
			effectText = t.eff,
			isBiS = t.bis,
			bisClass = t.bisC,
			bisVal = t.bisV,
			bisRank = t.bisR,
			bisTotal = t.bisT,
			bisBestName = t.bisBN,
			bisBestVal = t.bisBV,
			cd = t.cd,
			castTimeMs = t.ct,
			toolItemID = t.tool,
			anyChar = t.any == true,
		}
		ns.RECIPES[t.idx] = entry
		if entry.source == 'camp' and campSlots[entry.rep] then
			local pos = t.campOrd ~= nil and (t.campOrd + 1) or (#campSlots[entry.rep] + 1)
			campSlots[entry.rep][pos] = entry
		end
	end
	if not t.mmOnly then
		local pk = t.pk
		MP.RECIPES[pk] = MP.RECIPES[pk] or {}
		local m
		if t.mpOnly then
			m = {}
			for k, v in pairs(t) do
				if k ~= 'mpOnly' and k ~= 'pk' and k ~= 'mpIdx' and k ~= 'bySp' then m[k] = v end
			end
			m.prof = t.mpProf or pk
		else
			local mpR
			if t.mpR == false then mpR = nil
			elseif t.mpR ~= nil then mpR = t.mpR
			else mpR = cloneReagents(t.r) end
			m = {
				s = (t.mpS ~= nil) and t.mpS or t.s,
				i = (t.mpI ~= nil) and t.mpI or t.i,
				n = (t.mpN ~= nil) and t.mpN or t.n,
				c = mpVal(t.mpC, t.c or 1),
				req = (t.mpReq ~= nil) and t.mpReq or t.skill,
				y = t.y, g = t.g, gr = t.gr,
				src = t.mpSrc or t.acq,
				rlv = mpVal(t.mpRlv, t.rlv),
				elv = t.elv,
				tc = mpVal(t.mpTc, t.tc),
				ri = mpVal(t.mpRi, t.ri),
				rn = mpVal(t.mpRn, t.rn),
				rbuy = mpVal(t.mpRbuy, t.rbuy),
				fav = mpVal(t.mpFav, t.fav),
				rep = mpVal(t.mpRep, t.rep),
				repFacID = t.repFacID,
				repFac = t.repFac,
				vn = mpVal(t.vn, t.vAll),
				fac = t.fac, pre = t.pre, spec = t.spec, rod = t.rod, cd = t.cd, ct = t.ct,
				ench = mpVal(t.mpEnch, t.ench),
				bop = t.bop,
				r = mpR,
				prof = t.mpProf or pk,
			}
		end
		MP.RECIPES[pk][t.mpIdx] = m
		if t.bySp and m.s then MP.RECIPES_BY_SPELL[m.s] = m end
	end
end

function ns.GetRecipeCastTimeMs(spellID, rec)
	local spID = tonumber(spellID) or (type(rec) == 'table' and (tonumber(rec.spellID) or tonumber(rec.s))) or nil
	local function safeCastMs(v)
		if _G.issecretvalue and _G.issecretvalue(v) then return nil end
		if type(v) == 'number' and v >= 0 and v == v then return v end
		return nil
	end
	if spID and spID > 0 then
		if _G.C_Spell and type(_G.C_Spell.GetSpellInfo) == 'function' then
			local ok, info = pcall(_G.C_Spell.GetSpellInfo, spID)
			if ok and type(info) == 'table' and not (_G.issecrettable and _G.issecrettable(info)) then
				local liveMs = safeCastMs(info.castTime)
				if liveMs ~= nil then return liveMs end
			end
		end
		if type(_G.GetSpellInfo) == 'function' then
			local ok, _, _, _, castTime = pcall(_G.GetSpellInfo, spID)
			if ok then
				local liveMs = safeCastMs(castTime)
				if liveMs ~= nil then return liveMs end
			end
		end
		local staticMs = safeCastMs(ns.RECIPE_CAST_TIME_MS and ns.RECIPE_CAST_TIME_MS[spID])
		if staticMs ~= nil then return staticMs end
	end
	if type(rec) == 'table' then
		local recMs = safeCastMs(rec.castTimeMs)
		if recMs ~= nil then return recMs end
		recMs = safeCastMs(rec.ct)
		if recMs ~= nil then return recMs end
	end
	return 2000
end

