for rep, list in pairs(campSlots) do
	local target = ns.CAMP_RECIPES_BY_REP[rep]
	for _, e in ipairs(list) do target[#target + 1] = e end
end

-- Backfill Craftman's Writ numMade and reagents from ns.RECIPES when shared by spellID
do
	local bySpell = {}
	for _, rec in ipairs(ns.RECIPES) do
		if rec.spellID and not bySpell[rec.spellID] then bySpell[rec.spellID] = rec end
	end
	for _, w in ipairs(ns.WRITS or {}) do
		if w.reagents == nil and w.spellID and bySpell[w.spellID] then
			local rec = bySpell[w.spellID]
			w.numMade = w.numMade or rec.numMade
			w.reagents = cloneReagents(rec.reagents)
			for _, rg in ipairs(w.reagents or {}) do ns.ALL_CATALOG_IDS[rg[1]] = true end
		end
	end
end
